import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order: its people in the order they were
 *  added, a person's claims newest first. Each is opened as a single open would be (its next
 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures.
 *  A claim that is not on the sheet, is not a DRAFT, or is dated in a closed period is refused and
 *  left as it is. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        Map<Long, Person> persons = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
            persons.put(person.getId(), person);
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        int opened = 0;
        for (Claim claim : selected) {
            if (claim.getStatus() != ClaimStatus.DRAFT || closed(periods, claim)) {
                refused++;
                continue;
            }
            Rollup before = rollups.snapshot(sheet);
            if (!store.move(claim, claim.getStatus(), ClaimStatus.OPEN)) {
                refused++;
                continue;
            }
            claim.setStatus(ClaimStatus.OPEN);
            claim.setNumber(Numbering.next(sheet, claim.getDate(), store, settings, sheets, periods));
            claim.setOpenedBy(input.user());
            store.save(claim);
            Person person = persons.get(claim.getPersonId());
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(ClaimStatus.OPEN.event() + " sheet=" + sheet + " by=" + input.user() + " person="
                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
                    + " number=" + claim.getNumber());
            rollups.record(sheet, input.user(), before);
            opened++;
        }
        result.set(new BulkOpenResult(opened, refused));
    }

    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), claim.getDate());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;

/** A claim's figure: the due fixed when settled, else the figure its person's last statement bound it
 *  to (not while it is PENDING, which a statement does not bind), else its live due: its amount at the grade rate in force on its date, rounded as the sheet's
 *  {@link Rounding} has it, and
 *  at least the sheet's floor, except a correction's, which has no floor (null, n/a, when no rate applies). */
public final class ClaimFigure {
    private ClaimFigure() {
    }

    /** amount × pct ÷ 100, rounded by {@code mode} to two decimals; null when there is no rate. */
    public static BigDecimal of(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
        return pct == null ? null : amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
    }

    /** The live due: amount at pct, raised to the floor; null when there is no rate. */
    public static BigDecimal of(BigDecimal amount, BigDecimal pct, BigDecimal floor, RoundingMode mode) {
        BigDecimal due = of(amount, pct, mode);
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The figure the claim has now, given the grade's rate in force on its date and the sheet's floor. */
    public static BigDecimal of(Claim claim, BigDecimal pct, BigDecimal floor, Rounding rounding) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        RoundingMode mode = rounding.mode(claim);
        return claim.isCorrection() ? of(claim.getAmount(), pct, mode) : of(claim.getAmount(), pct, floor, mode);
    }
}
